/**
 * Friendly names for the types generated from docs/openapi.yaml.
 * Regenerate the source with `npm run generate`; never edit src/generated by hand.
 */
import type { components, operations } from "./generated/openapi.js";

type Schemas = components["schemas"];
type Query<Op extends keyof operations> = NonNullable<operations[Op]["parameters"]["query"]>;

